package com.example.berexplorer.util;
import java.util.Base64;
public final class Hex { private Hex(){} public static byte[] parse(String s){String x=s.replaceAll("(?s)\\s+","").replace("0x","").replace("0X",""); if(x.length()%2!=0)throw new IllegalArgumentException("Hex input has an odd number of digits"); byte[] b=new byte[x.length()/2]; for(int i=0;i<b.length;i++){int a=Character.digit(x.charAt(i*2),16),c=Character.digit(x.charAt(i*2+1),16);if(a<0||c<0)throw new IllegalArgumentException("Invalid hex near position "+(i*2));b[i]=(byte)((a<<4)|c);}return b;} public static byte[] base64(String s){try{return Base64.getDecoder().decode(s.replaceAll("\\s+",""));}catch(Exception e){throw new IllegalArgumentException("Invalid Base64: "+e.getMessage());}} public static String format(byte[] b){StringBuilder s=new StringBuilder();for(int i=0;i<b.length;i++){if(i%16==0){if(i>0)s.append('\n');s.append(String.format("%04X  ",i));}else if(i%8==0)s.append("  ");else s.append(' ');s.append(String.format("%02X",b[i]));}return s.toString();}}
